#include "ciallo/container/unordered_flat_map.hpp"

#include <benchmark/benchmark.h>

#include <chrono>
#include <random>
#include <unordered_set>

/// @brief
///   Get the global random seed shared by all benchmarks.
/// @return
///   A seed generated by @c std::random_device once per process.
static std::mt19937::result_type make_random_seed() {
    static const std::mt19937::result_type seed = std::random_device{}();
    return seed;
}

/// @brief
///   Generate a set of unique random keys.
/// @tparam Key
///   Type of the keys. Only @c std::uint32_t and @c std::string are supported.
/// @param count
///   Number of keys to generate.
/// @return
///   Vector containing @p count unique random keys.
template <typename Key>
static std::vector<Key> make_random_keys(std::mt19937 &engine, std::size_t count) {
    std::vector<Key> keys;
    keys.reserve(count);

    std::unordered_set<Key> seen;
    seen.reserve(count);

    if constexpr (std::is_same_v<Key, std::string>) {
        std::uniform_int_distribution<std::size_t> length_distribution(5, 32);
        std::uniform_int_distribution<int> char_distribution('!', '~');

        while (keys.size() < count) {
            std::string key(length_distribution(engine), '\0');
            for (char &ch : key) {
                ch = static_cast<char>(char_distribution(engine));
            }
            if (seen.insert(key).second) {
                keys.push_back(std::move(key));
            }
        }
    } else {
        std::uniform_int_distribution<Key> distribution;

        while (keys.size() < count) {
            Key key = distribution(engine);
            if (seen.insert(key).second) {
                keys.push_back(key);
            }
        }
    }

    return keys;
}

template <typename Key>
static void unordered_flat_map_insert(benchmark::State &state) {
    const auto count = static_cast<std::size_t>(state.range(0));
    std::mt19937 engine(make_random_seed());

    ciallo::unordered_flat_map<Key, std::size_t> map;
    std::vector<Key> keys;
    for (auto _ : state) {
        keys = make_random_keys<Key>(engine, count);
        map.clear();

        const auto start = std::chrono::steady_clock::now();
        for (const Key &key : keys) {
            map.insert({key, 0});
        }
        const auto end = std::chrono::steady_clock::now();
        state.SetIterationTime(std::chrono::duration<double>(end - start).count());

        benchmark::DoNotOptimize(map);
    }
}

template <typename Key>
static void unordered_flat_map_erase(benchmark::State &state) {
    const auto count = static_cast<std::size_t>(state.range(0));
    std::mt19937 engine(make_random_seed());

    ciallo::unordered_flat_map<Key, std::size_t> map;
    std::vector<Key> keys;
    for (auto _ : state) {
        keys = make_random_keys<Key>(engine, count);
        map.clear();
        for (const Key &key : keys) {
            map.insert({key, 0});
        }

        const auto start = std::chrono::steady_clock::now();
        for (const Key &key : keys) {
            benchmark::DoNotOptimize(map.erase(key));
        }
        const auto end = std::chrono::steady_clock::now();
        state.SetIterationTime(std::chrono::duration<double>(end - start).count());
    }
}

